mapper.update:
UPDATE resume_version
SET sections_json = #{sectionsJson},
    change_summary = #{changeSummary},
    updated_at = #{updatedAt}
WHERE id = #{versionId}
  AND resume_id = #{resumeId}
  AND status = 'DRAFT'
  AND updated_at = #{expectedUpdatedAt}

UPDATE resume_version
SET status = 'FINAL',
    source_snapshot_json = #{sourceSnapshotJson},
    change_summary = #{changeSummary},
    updated_at = #{updatedAt}
WHERE id = #{versionId}
  AND resume_id = #{resumeId}
  AND status = 'DRAFT'

UPDATE resume_version
SET pdf_storage_ref = #{storageRef},
    pdf_generated_at = #{generatedAt}
WHERE id = #{versionId} AND resume_id = #{resumeId}
